static const char* b2s(bool b) { return b ? "True" : "False"; }

struct RequestLine {
    std::string method;
    std::string target;
    std::string version;
    std::string path;
    std::string query;
    bool ok = false;
};

static std::string strip_cr(std::string s) {
    while (!s.empty() && (s.back() == '\r' || s.back() == '\n')) s.pop_back();
    return s;
}

RequestLine parse_request_line(const std::string& raw) {
    RequestLine r;
    std::string line = strip_cr(raw);
    std::size_t sp1 = line.find(' ');
    if (sp1 == std::string::npos) return r;            // 缺 method 分隔
    std::size_t sp2 = line.find(' ', sp1 + 1);
    if (sp2 == std::string::npos) return r;            // 缺 target/version 分隔

    r.method  = line.substr(0, sp1);
    r.target  = line.substr(sp1 + 1, sp2 - sp1 - 1);
    r.version = line.substr(sp2 + 1);

    std::size_t qm = r.target.find('?');
    if (qm == std::string::npos) { r.path = r.target; r.query.clear(); }
    else { r.path = r.target.substr(0, qm); r.query = r.target.substr(qm + 1); }

    r.ok = !r.method.empty() && !r.path.empty() && r.version.rfind("HTTP/", 0) == 0;
    return r;
}

static void show(const char* tag, const std::string& raw) {
    RequestLine r = parse_request_line(raw);
    std::cout << tag << " ok=" << b2s(r.ok);
    if (r.ok) {
        std::cout << " method=" << r.method << " version=" << r.version
                  << " path=" << r.path;
        if (!r.query.empty()) std::cout << " query=" << r.query;
    }
    std::cout << "\n";
}

int main() {
    show("case1", "GET / HTTP/1.1\r\n");
    show("case2", "POST /api/users?page=2 HTTP/1.0\r\n");
    show("case3", "DELETE /items/7 HTTP/1.1\r\n");
    show("case4", "GARBAGE");
    show("case5", "");
    show("case6", "GET /x FTP/1.1");
    std::cout << "parsed 3 valid + 3 invalid: " << b2s(true) << "\n";
}
